package com.example;

import com.lowagie.text.DocumentException;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.rendering.PDFRenderer;
import org.xhtmlrenderer.pdf.ITextRenderer;


import org.xhtmlrenderer.simple.Graphics2DRenderer;
import org.xhtmlrenderer.util.XRLog;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
public class HtmlToImageDemo {
    public static void main(String[] args) {

        // 可选：关闭日志
        XRLog.setLoggingEnabled(false);
        System.setProperty("java.awt.headless", "true");

        // 关闭日志（可选）
        XRLog.setLoggingEnabled(false);
        // 启用 headless（即使 Windows 也建议开启，避免潜在问题）
        System.setProperty("java.awt.headless", "true");

        // ✅ 你的富文本 HTML（支持 table / p / img base64）
        String htmlContent =
                "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n" +
                        "<html xmlns=\"http://www.w3.org/1999/xhtml\">\n" +
                        "<head>\n" +
                        "  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=UTF-8\" />\n" +
                        "</head>\n" +
                        "<body>\n" +
                        "  <p>This is a test paragraph with <strong>bold text</strong>.</p>\n" +
                        "  <p>Table below:</p>\n" +
                        "  <table>\n" +
                        "    <tr>\n" +
                        "      <td>Item</td>\n" +
                        "      <td>Status</td>\n" +
                        "    </tr>\n" +
                        "    <tr>\n" +
                        "      <td>Signature</td>\n" +
                        "      <td>Completed</td>\n" +
                        "    </tr>\n" +
                        "    <tr>\n" +
                        "      <td>Approval</td>\n" +
                        "      <td>Approved</td>\n" +
                        "    </tr>\n" +
                        "  </table>\n" +
                        "  <p>Image (green check):</p>\n" +
                        "  <img src=\"data:image/png;base64,\" alt=\"check\" />\n" +
                        "</body>\n" +
                        "</html>";
//        htmlContent = makeXhtml(htmlContent);
        try {
            // ✅ 第一步：HTML → PDF（内存）
            ByteArrayOutputStream pdfOut = new ByteArrayOutputStream();
            ITextRenderer renderer = new ITextRenderer();
            // 包装为完整 XHTML
            String fullHtml =makeXhtml(htmlContent);
            renderer.setDocumentFromString(fullHtml);
            renderer.layout();
            renderer.createPDF(pdfOut);

            // ✅ 第二步：PDF → BufferedImage
            try (PDDocument doc = PDDocument.load(pdfOut.toByteArray())) {
                PDFRenderer pdfRenderer = new PDFRenderer(doc);
                // 1.5f ≈ 144 DPI，清晰度足够；可调整
                BufferedImage image = pdfRenderer.renderImage(0, 1.5f);

                // ✅ 第三步：保存图片
                ImageIO.write(image, "png", new File("output.png"));
                System.out.println("✅ output.png 生成成功");
            }

        } catch (IOException | DocumentException e) {
            e.printStackTrace();
        }
    }

    private static String makeXhtml(String htmlFragment) {
        Document doc = Jsoup.parseBodyFragment(htmlFragment);
        doc.outputSettings()
                .syntax(Document.OutputSettings.Syntax.xml)
                .escapeMode(org.jsoup.nodes.Entities.EscapeMode.xhtml);

        return
                "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n" +
                        "<html xmlns=\"http://www.w3.org/1999/xhtml\">\n" +
                        "<head>\n" +
                        "  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=UTF-8\" />\n" +
                        "  <style>\n" +
                        "    body { font-family: sans-serif; margin: 10px; }\n" +
                        "    table { border-collapse: collapse; width: 100%; }\n" +
                        "    td, th { border: 1px solid #000; padding: 6px; }\n" +
                        "  </style>\n" +
                        "</head>\n" +
                        "<body>" + doc.body().html() + "</body>\n" +
                        "</html>";
    }

}